        'ai-disclaimer': section('29. Застереження щодо ШІ', paragraph('Інформацію, створену ШІ, слід перевірити за участю кваліфікованого фахівця перед тим, як покладатися на неї. LEOKA не гарантує придатність результатів ШІ для конкретної мети. Ви самостійно відповідаєте за рішення, дії та наслідки, що ґрунтуються на таких результатах.')),
        'limitation-of-liability': section('30. Обмеження відповідальності', paragraph('У МАКСИМАЛЬНИХ МЕЖАХ, ДОЗВОЛЕНИХ ЗАКОНОМ, GREEN CRAFT LLC, ЇЇ ЛІЦЕНЗІАРИ, ПОСТАЧАЛЬНИКИ ПОСЛУГ І ПРЕДСТАВНИКИ НЕ ВІДПОВІДАЮТЬ ЗА НЕПРЯМІ, ВИПАДКОВІ, СПЕЦІАЛЬНІ, ПОБІЧНІ, ПОКАРАЛЬНІ ЧИ ШТРАФНІ ЗБИТКИ, А ТАКОЖ ЗА ВТРАТУ ПРИБУТКУ, ДОХОДУ, ДАНИХ, ДІЛОВОЇ РЕПУТАЦІЇ АБО БІЗНЕС-МОЖЛИВОСТЕЙ, ЩО ВИНИКАЮТЬ У ЗВ’ЯЗКУ ІЗ СЕРВІСАМИ АБО ЦИМИ УМОВАМИ. НАША СУКУПНА ВІДПОВІДАЛЬНІСТЬ ОБМЕЖУЄТЬСЯ В МЕЖАХ, ДОЗВОЛЕНИХ ЗАСТОСОВНИМ ЗАКОНОМ. ЦІ УМОВИ НЕ ОБМЕЖУЮТЬ ВІДПОВІДАЛЬНІСТЬ, ЯКУ ЗА ЗАКОНОМ НЕ МОЖНА ОБМЕЖИТИ АБО ВИКЛЮЧИТИ.')),
        indemnification: section('31. Відшкодування збитків', paragraph('У межах, дозволених законом, ви погоджуєтеся захищати Green Craft LLC, її афілійованих осіб, ліцензіарів, постачальників послуг, посадових осіб, працівників і представників, відшкодовувати їм збитки та звільняти їх від відповідальності за претензіями, шкодою, зобов’язаннями, втратами, витратами й видатками, що виникають у зв’язку з порушенням вами цих Умов, неналежним використанням Сервісів, порушенням закону або прав третіх осіб, несанкціонованим використанням інтеграцій чи Контентом користувача.')),
        'governing-law': section('32. Застосовне право', paragraph('Ці Умови та спори, що виникають із них, регулюються законодавством штату Делавер, США, без урахування колізійних норм, з урахуванням імперативних вимог застосовного законодавства. Ці умови про застосовне право можуть уточнюватися в окремій письмовій угоді або після остаточної юридичної перевірки без зміни решти Умов.')),
        'dispute-resolution': section('33. Вирішення спорів', paragraph('Сторони спершу добросовісно намагатимуться врегулювати спір шляхом письмового повідомлення та неформального обговорення. Якщо неформально врегулювати спір не вдасться, його можна передати на розгляд компетентного суду відповідно до умов про застосовне право штату Делавер, якщо окрема письмова угода не передбачає іншої законної процедури. Цей розділ не перешкоджає жодній зі сторін звернутися за невідкладним судовим захистом, якщо це дозволено законом.')),
        'changes-to-terms': section('34. Зміни до Умов', paragraph('Green Craft LLC може час від часу оновлювати ці Умови. За потреби про суттєві зміни буде повідомлено належним чином, а на цій сторінці буде зазначено дату оновлення. Якщо це дозволено законом, подальше користування Сервісами після набрання змінами чинності може означати їх прийняття.')),
        severability: section('35. Подільність положень', paragraph('Якщо будь-яке положення цих Умов буде визнано таким, що не підлягає виконанню, його буде змінено або обмежено лише в мінімально необхідному обсязі, а решта положень залишатиметься чинною в межах, дозволених законом.')),
        waiver: section('36. Відмова від права', paragraph('Невикористання права вимагати виконання будь-якого положення цих Умов не означає відмови від права вимагати його або будь-якого іншого положення в майбутньому.')),
        'entire-agreement': section('37. Повнота угоди', paragraph('Ці Умови разом із Політикою конфіденційності, Політикою щодо файлів cookie, сторінкою про доступність, застосовними умовами замовлення чи підписки та іншими згаданими тут угодами регулюють користування Сервісами, з урахуванням окремої письмової угоди.')),
        assignment: section('38. Передавання прав та обов’язків', paragraph('Ви не можете передавати ці Умови або свої права чи обов’язки за ними без нашої попередньої письмової згоди, за винятком випадків, дозволених законом. Green Craft LLC може передати ці Умови в межах злиття, придбання, реорганізації, продажу активів або іншого передавання бізнесу.')),
        'force-majeure': section('39. Обставини непереборної сили', paragraph('Жодна зі сторін не відповідає за затримку чи невиконання зобов’язань через події поза її розумним контролем, зокрема стихійні лиха, збої інфраструктури, перебої в роботі інтернету, дії органів влади, війну, громадські заворушення, трудові конфлікти, збої сторонніх сервісів або інші обставини непереборної сили.')),
